def encrypt(text: str) -> str:
    """
    Encrypts lowercase letters by shifting them 4 positions forward in the alphabet,
    wrapping around after 'z'. Non-lowercase characters remain unchanged.
    """
    return ''.join(
        chr((ord(c) - ord('a') + 4) % 26 + ord('a')) if 'a' <= c <= 'z' else c
        for c in text
    )

