def sum_first_k_at_most_2_digits(arr, k):
    """
    Sum the first k elements of arr that have at most 2 digits (ignoring sign).

    Args:
        arr: List of numbers
        k: Number of elements to sum

    Returns:
        Sum of the first k elements that have at most 2 digits
    """
    return sum(
        x for x in arr 
        if len(str(abs(x))) <= 2
    ) if k >= len([x for x in arr if len(str(abs(x))) <= 2]) else sum(
        next(x for i, x in enumerate(arr) if len(str(abs(x))) <= 2) 
        for _ in range(k)
    )

