import sys

def shift_char(c: str, offset: int) -> str:
    if 'a' <= c <= 'z':
        return chr((ord(c) - ord('a') + offset) % 26 + ord('a')))
    return c

def encode(text: str) -> str:
    return ''.join(shift_char(ch, 5) for ch in text)

def decode(text: str) -> str:
    return ''.join(shift_char(ch, -5) for ch in text)

